237	        let handle = spawn(async move {
238	            // Every 30 seconds we emit a heartbeat – useful for UI that
239	            // wishes to animate the canvas even without new events.
240	            let mut heartbeat = tokio::time::interval(Duration::from_secs(30));
241	
242	            // Maintain a mutable, in-flight copy we can diff against.
243	            let mut current = tx_clone.borrow().clone();
244	
245	            loop {
246	                select! {
247	                    _ = heartbeat.tick() => {
248	                        // Nothing to update → continue loop.
249	                        continue;
250	                    }
251	                    evt = event_rx.recv() => {
252	                        match evt {
253	                            Ok(domain_evt) => {
254	                                if update_state(&mut current, domain_evt) {
255	                                    // Push new immutable snapshot to observers.
256	                                    let _ = tx_clone.send_replace(current.clone());
257	                                }
