260	                            // happens we bail out to avoid hung task.
261	                            Err(broadcast::error::RecvError::Closed) => break,
262	                            // Lagged behind ➜ skip lost messages.
263	                            Err(broadcast::error::RecvError::Lagged(_)) => continue,
264	                        }
