342	/// Very fast, not-cryptographic hash function for demo purposes.
343	fn fast_hash(input: u64) -> u64 {
344	    let mut x = input;
345	    x ^= x >> 30;
346	    x = x.wrapping_mul(0xbf58476d1ce4e5b9);
347	    x ^= x >> 27;
348	    x = x.wrapping_mul(0x94d049bb133111eb);
349	    x ^ (x >> 31)
350	}
