352	/// Returns the hue (0–360°) of the most abundant colour.
353	///
354	/// A “real” implementation would integrate with the `palette` crate,
355	/// cluster LAB space, etc.  Here we fake it by averaging RGB over the
356	/// first 4 colours, then converting to HSV.
357	fn dominant_hue(palette: &ColorPalette) -> Option<f32> {
358	    use palette::{FromColor, Hsv, Srgb};
359	
360	    let count = palette.colors.len().min(4);
361	    if count == 0 {
362	        return None;
363	    }
364	
365	    let (mut r, mut g, mut b) = (0f32, 0f32, 0f32);
366	    for c in palette.colors.iter().take(count) {
367	        r += c.r as f32 / 255.0;
368	        g += c.g as f32 / 255.0;
369	        b += c.b as f32 / 255.0;
370	    }
371	    r /= count as f32;
372	    g /= count as f32;
373	    b /= count as f32;
374	
375	    let hsv: Hsv = Hsv::from_color(Srgb::new(r, g, b));
376	    Some(hsv.hue.to_positive_degrees() as f32)
377	}
