168	/// Simple, deterministic strategy baked into the core.
169	#[derive(Default, Debug)]
170	pub struct DefaultGenerator;
171	
172	impl PaletteGenerator for DefaultGenerator {
173	    fn generate(&self, ctx: &GenerationContext) -> Palette {
174	        // ------------------------------------------------------------------ //
175	        // Seed selection
176	        // ------------------------------------------------------------------ //
177	        let seed = ctx.seed.unwrap_or_else(|| {
178	            ctx.location
179	                .map(|l| (l.lat.to_bits() ^ l.lon.to_bits()) as u64)
180	                .unwrap_or_else(|| Uuid::new_v4().as_u128() as u64)
181	        });
182	        let mut rng = StdRng::seed_from_u64(seed);
183	
184	        // ------------------------------------------------------------------ //
185	        // How many colours?  The more movement, the larger the palette.
186	        // ------------------------------------------------------------------ //
187	        let movement_energy: f32 = ctx
188	            .motion_samples
189	            .iter()
190	            .map(|m| m.acceleration.abs() + m.rotation_rate.abs())
191	            .sum();
192	        let colour_count = ((movement_energy / 5.0).clamp(4.0, 12.0)) as usize;
193	
194	        // ------------------------------------------------------------------ //
195	        // Generate colours.
196	        // ------------------------------------------------------------------ //
197	        let mut colours = Vec::with_capacity(colour_count);
198	        for _ in 0..colour_count {
199	            let mut c = Color::random(&mut rng);
200	
201	            // Brighten or darken based on ambient luminosity.
202	            if let Some(lux) = ctx.ambient_lux {
203	                let scale = if lux < 100.0 {
204	                    0.8
205	                } else if lux > 500.0 {
206	                    1.2
207	                } else {
208	                    1.0
209	                };
210	                c = Color::new(
211	                    ((c.r as f32 * scale).min(255.0)) as u8,
212	                    ((c.g as f32 * scale).min(255.0)) as u8,
213	                    ((c.b as f32 * scale).min(255.0)) as u8,
214	                    c.a,
215	                );
216	            }
217	
218	            colours.push(c);
219	        }
220	
221	        Palette {
222	            id: PaletteId::new(),
223	            colors: colours,
224	            meta: PaletteMeta {
225	                created_at: Utc::now(),
226	                location: ctx.location,
227	                luminosity: ctx.ambient_lux,
228	                weather_icon: ctx.weather_icon.clone(),
229	            },
230	        }
231	    }
232	}
