259	/// A subscriber callback.
260	type Callback = Arc<dyn Fn(&DomainEvent) + Send + Sync>;
261	
262	/// Opaque handle returned when subscribing.
263	#[derive(Debug, Clone, PartialEq, Eq, Hash)]
264	pub struct SubscriptionToken(Uuid);
265	
266	static SUBSCRIBERS: Lazy<Mutex<HashMap<SubscriptionToken, Callback>>> =
267	    Lazy::new(|| Mutex::new(HashMap::new()));
268	
269	/// Process-wide, thread-safe observer bus.
270	pub struct EventBus;
271	
272	impl EventBus {
273	    /// Listen to every domain event.
274	    pub fn subscribe(cb: Callback) -> SubscriptionToken {
275	        let token = SubscriptionToken(Uuid::new_v4());
276	        SUBSCRIBERS
277	            .lock()
278	            .expect("subscriber lock poisoned")
279	            .insert(token.clone(), cb);
280	        token
281	    }
282	
283	    /// Remove a subscription.
284	    pub fn unsubscribe(token: SubscriptionToken) {
285	        SUBSCRIBERS
286	            .lock()
287	            .expect("subscriber lock poisoned")
288	            .remove(&token);
289	    }
290	
291	    /// Broadcast an event to all subscribers on background threads.
292	    pub fn publish(event: DomainEvent) {
293	        let callbacks = {
294	            SUBSCRIBERS
295	                .lock()
296	                .expect("subscriber lock poisoned")
297	                .values()
298	                .cloned()
299	                .collect::<Vec<_>>()
300	        };
301	
302	        for cb in callbacks {
303	            let evt = event.clone();
304	            thread::spawn(move || (cb)(&evt));
305	        }
306	    }
307	}
