73	/// Platform-agnostic interface for a stream of geo-spatial updates.
74	///
75	/// Implementations are expected to:
76	///
77	/// • perform any heavy initialisation work in `init()` (permission checks,
78	///   client/fused‐provider setup, etc.);
79	/// • launch an internal task that pushes samples through a
80	///   `broadcast::Sender<GeoPoint>`; and
81	/// • hand out attached receivers via `subscribe()`.
82	#[async_trait]
83	pub trait LocationProvider: Send + Sync {
84	    async fn init(&self) -> Result<()>;
85	    async fn subscribe(&self) -> Result<broadcast::Receiver<GeoPoint>>;
86	    fn has_permission(&self) -> bool;
