89	// ─────────────────────────────────────────────────────────────────────────────
90	// Mock provider – used on desktop, CI, or when hardware sensors are missing.
91	// Emits a synthetic circular walk path every second.
92	// ─────────────────────────────────────────────────────────────────────────────
93	
94	pub struct MockLocationProvider {
95	    tx: broadcast::Sender<GeoPoint>,
96	    started: Mutex<bool>,
97	}
98	
99	impl MockLocationProvider {
100	    pub fn new() -> Self {
101	        let (tx, _) = broadcast::channel(32);
102	        Self {
103	            tx,
104	            started: Mutex::new(false),
105	        }
106	    }
107	
108	    async fn emit_loop(tx: broadcast::Sender<GeoPoint>) {
109	        let mut theta = 0.0_f64;
110	        let centre_lat = 37.7749;
111	        let centre_lng = -122.4194;
112	        let radius = 0.001; // ≈ 111 m
113	
114	        loop {
115	            theta = (theta + 0.05) % (2.0 * std::f64::consts::PI);
116	
117	            let _ = tx.send(GeoPoint {
118	                latitude: centre_lat + radius * theta.cos(),
119	                longitude: centre_lng + radius * theta.sin(),
120	                altitude: Some(12.0),
121	                accuracy: Some(5.0),
122	                timestamp: SystemTime::now(),
123	            });
124	
125	            time::sleep(Duration::from_secs(1)).await;
126	        }
127	    }
128	}
