130	#[async_trait]
131	impl LocationProvider for MockLocationProvider {
132	    async fn init(&self) -> Result<()> {
133	        let mut started = self.started.lock().await;
134	        if *started {
135	            return Ok(());
136	        }
137	
138	        let tx_clone = self.tx.clone();
139	        tokio::spawn(async move { Self::emit_loop(tx_clone).await });
140	        *started = true;
141	
142	        Ok(())
143	    }
144	
145	    async fn subscribe(&self) -> Result<broadcast::Receiver<GeoPoint>> {
146	        Ok(self.tx.subscribe())
147	    }
148	
149	    fn has_permission(&self) -> bool {
150	        true
151	    }
152	}
