172	
173	pub struct LocationService {
174	    provider: Arc<dyn LocationProvider>,
175	    bus: EventBus,
176	    telemetry: Telemetry,
177	    started: Mutex<bool>,
178	}
179	
180	impl LocationService {
181	    /// Global instance accessor.
182	    pub fn instance() -> &'static Arc<Self> {
183	        static INSTANCE: Lazy<Arc<LocationService>> = Lazy::new(|| {
184	            Arc::new(LocationService {
185	                provider: LocationProviderFactory::create(),
186	                bus: EventBus::global(),
187	                telemetry: Telemetry::global(),
188	                started: Mutex::new(false),
189	            })
190	        });
191	        &INSTANCE
192	    }
193	
194	    /// Ensures the background listener task is running.
195	    pub async fn ensure_started(self: &Arc<Self>) -> Result<()> {
196	        let mut started_guard = self.started.lock().await;
197	        if *started_guard {
198	            return Ok(());
199	        }
200	
201	        // Provider initialisation may include permission prompts, etc.
202	        self.provider.init().await?;
203	
204	        let mut rx = self.provider.subscribe().await?;
205	        let bus = self.bus.clone();
206	        let telemetry = self.telemetry.clone();
207	
208	        tokio::spawn(async move {
209	            loop {
210	                select! {
211	                    sample = rx.recv() => match sample {
212	                        Ok(point) => {
213	                            let event = DomainEvent::LocationUpdated(LocationUpdated {
214	                                latitude:  point.latitude,
215	                                longitude: point.longitude,
216	                                altitude:  point.altitude,
217	                                accuracy:  point.accuracy,
218	                                timestamp: point.timestamp,
219	                            });
220	
221	                            if let Err(e) = bus.dispatch(event).await {
222	                                tracing::error!(error=?e, "failed to dispatch LocationUpdated");
223	                            }
224	                        }
225	                        Err(broadcast::error::RecvError::Lagged(skipped)) => {
226	                            telemetry.increment_counter("location.lagged_samples", skipped as u64);
227	                            tracing::warn!(skipped, "location receiver lagged behind");
228	                        }
229	                        Err(broadcast::error::RecvError::Closed) => {
230	                            tracing::warn!("location provider channel closed; terminating task");
231	                            break;
232	                        }
233	                    }
234	                }
235	            }
236	        });
237	
238	        *started_guard = true;
239	        Ok(())
240	    }
241	
242	    /// Returns the most recent GPS fix if available.
243	    ///
244	    /// This is a best-effort helper for synchronous callers (e.g. splash-screen
245	    /// quick start). It attaches a fresh receiver, grabs its first message, and
246	    /// returns it. No guarantee is made about the age or freshness of the fix.
247	    pub async fn last_known(&self) -> Option<GeoPoint> {
248	        self.provider
249	            .subscribe()
250	            .await
251	            .ok()
252	            .and_then(|mut rx| rx.recv().await.ok())
253	    }
254	}
