164	impl<P, B> MonetizationService<P, B>
165	where
166	    P: InAppPurchaseProvider + 'static,
167	    B: EventBus<MonetizationEvent> + 'static,
168	{
169	    fn new(provider: Arc<P>, bus: Arc<B>) -> Arc<Self> {
170	        Arc::new(Self {
171	            provider,
172	            bus,
173	            purchased: Mutex::new(HashMap::new()),
174	        })
175	    }
