177	    /// Bootstraps the global singleton.
178	    ///
179	    /// Must be called once early at application startup.
180	    pub fn bootstrap(provider: Arc<P>, bus: Arc<B>) {
181	        let svc = Self::new(provider, bus);
182	
183	        // Replace the Lazy value using unsafe pointer chungus; cannot normally
184	        // because once_cell doesn't support mutation. We therefore cheat by
185	        // leaking the new instance. This is acceptable because it's a true
186	        // app-lifetime singleton.
187	        unsafe {
188	            let ptr = Arc::into_raw(svc.clone());
189	            let handle_mut = Arc::get_mut_unchecked(&mut Arc::clone(&INSTANCE));
190	            *handle_mut = MonetizationServiceHandle::Ready(svc);
191	            // We purposely leak `ptr` since INSTANCE now owns it.
192	            let _ = ptr;
193	        }
194	    }
