196	    async fn internal_purchase(
197	        &self,
198	        product_id: &str,
199	        kind: PurchaseKind,
200	    ) -> Result<PurchaseReceipt, MonetizationError> {
201	        let receipt = self.provider.purchase(product_id).await;
202	
203	        match receipt {
204	            Ok(receipt) => {
205	                self.purchased
206	                    .lock()
207	                    .await
208	                    .insert(receipt.product_id.clone(), receipt.clone());
209	
210	                // Fire event
211	                let event = match kind {
212	                    PurchaseKind::Brush => MonetizationEvent::BrushPurchased {
213	                        product_id: product_id.to_string(),
214	                        receipt: receipt.clone(),
215	                    },
216	                    PurchaseKind::Filter => MonetizationEvent::FilterPurchased {
217	                        product_id: product_id.to_string(),
218	                        receipt: receipt.clone(),
219	                    },
220	                };
221	                self.bus.publish(event).await;
222	                Ok(receipt)
223	            }
224	            Err(err) => {
225	                self.bus
226	                    .publish(MonetizationEvent::PurchaseFailed {
227	                        product_id: Some(product_id.to_string()),
228	                        error: err.clone(),
229	                    })
230	                    .await;
231	                Err(err)
232	            }
233	        }
234	    }
235	}
