235	/// Persist JSON to a temp file then atomically rename.
236	///
237	/// If `key` is given and the feature `biometric_auth` is active, the payload
238	/// is encrypted before writing.
239	async fn write_json_atomically<T: Serialize>(
240	    dest: &Path,
241	    value: &T,
242	    key: Option<[u8; 32]>,
243	) -> Result<(), StorageError> {
244	    let dir = dest
245	        .parent()
246	        .ok_or_else(|| StorageError::Io(dest.display().to_string(), std::io::ErrorKind::NotFound.into()))?;
247	    let tmp = dir.join(format!(".{}.tmp", uuid::Uuid::new_v4()));
248	
249	    let json = serde_json::to_vec_pretty(value)?;
250	    let payload = maybe_encrypt(&json, key)?;
251	
252	    fs::write(&tmp, payload)
253	        .await
254	        .map_err(|e| StorageError::Io(tmp.to_string_lossy().into_owned(), e))?;
255	    fs::rename(&tmp, dest)
256	        .await
257	        .map_err(|e| StorageError::Io(dest.to_string_lossy().into_owned(), e))?;
258	    Ok(())
259	}
