261	/// Load and deserialize every JSON file in `dir`.
262	async fn load_dir<T>(dir: &Path, key: Option<[u8; 32]>) -> Result<Vec<T>, StorageError>
263	where
264	    T: DeserializeOwned + Send + 'static,
265	{
266	    let mut items = Vec::new();
267	    let mut entries = fs::read_dir(dir)
268	        .await
269	        .map_err(|e| StorageError::Io(dir.display().to_string(), e))?;
270	
271	    while let Some(entry) = entries
272	        .next_entry()
273	        .await
274	        .map_err(|e| StorageError::Io(dir.display().to_string(), e))?
275	    {
276	        let path = entry.path();
277	        if path.extension().and_then(|s| s.to_str()) != Some("json") {
278	            continue;
279	        }
280	
281	        match fs::read(&path).await {
282	            Ok(bytes) => {
283	                let bytes = maybe_decrypt(&bytes, key)?;
284	                match serde_json::from_slice::<T>(&bytes) {
285	                    Ok(item) => items.push(item),
286	                    Err(e) => log::warn!("Skipping corrupt file {:?}: {}", path, e),
287	                }
288	            }
289	            Err(e) => {
290	                log::warn!("Failed reading file {:?}: {}", path, e);
291	            }
292	        }
293	    }
294	
295	    Ok(items)
296	}
