298	/// Encrypt payload with AES-256-GCM when the `biometric_auth` feature is
299	/// enabled & key provided.  Otherwise returns original bytes.
300	fn maybe_encrypt(buf: &[u8], key: Option<[u8; 32]>) -> Result<Vec<u8>, StorageError> {
301	    #[cfg(all(feature = "biometric_auth", feature = "ring"))]
302	    {
303	        use ring::aead::*;
304	        if let Some(key) = key {
305	            let sealing_key = LessSafeKey::new(UnboundKey::new(&AES_256_GCM, &key).unwrap());
306	            let mut in_out = buf.to_vec();
307	            sealing_key
308	                .seal_in_place_append_tag(
309	                    Nonce::assume_unique_for_key([0u8; 12]),
310	                    Aad::empty(),
311	                    &mut in_out,
312	                )
313	                .map_err(|_| StorageError::Encryption("seal failed"))?;
314	            return Ok(in_out);
315	        }
316	    }
317	    Ok(buf.to_vec())
318	}
319	
320	/// Decrypt payload when needed (see `maybe_encrypt`).
321	fn maybe_decrypt(buf: &[u8], key: Option<[u8; 32]>) -> Result<Vec<u8>, StorageError> {
322	    #[cfg(all(feature = "biometric_auth", feature = "ring"))]
323	    {
324	        use ring::aead::*;
325	        if let Some(key) = key {
326	            let opening_key = LessSafeKey::new(UnboundKey::new(&AES_256_GCM, &key).unwrap());
327	            let mut in_out = buf.to_vec();
328	            let decrypted = opening_key
329	                .open_in_place(
330	                    Nonce::assume_unique_for_key([0u8; 12]),
331	                    Aad::empty(),
332	                    &mut in_out,
333	                )
334	                .map_err(|_| StorageError::Encryption("open failed"))?;
335	            return Ok(decrypted.to_vec());
336	        }
337	    }
338	    Ok(buf.to_vec())
339	}
