157	/// Thread-safe singleton dispatching [`DomainEvent`]s to any number of
158	/// interested parties.
159	///
160	/// Internally backed by a `crossbeam` multi-producer multi-consumer channel.
161	pub struct EventBus {
162	    // A write lock is only needed when a new subscriber is created, therefore
163	    // keeping the hot path (`publish`) free from blocking.
164	    subscribers: RwLock<Vec<Sender<Arc<DomainEvent>>>>,
165	}
166	
167	impl EventBus {
168	    /// Global access point to the singleton bus.
169	    ///
170	    /// Lazily initialised on first use to avoid "static initialization order"
171	    /// issues and keep start-up times low.
172	    pub fn global() -> &'static Self {
173	        static INSTANCE: Lazy<EventBus> = Lazy::new(|| EventBus {
174	            subscribers: RwLock::new(Vec::with_capacity(8)),
175	        });
176	        &INSTANCE
177	    }
178	
179	    /// Publish a new [`DomainEvent`] to every current subscriber.
180	    ///
181	    /// Failures are logged and otherwise ignored so a rogue receiver cannot
182	    /// bring the whole system down.
183	    pub fn publish(&self, event: DomainEvent) {
184	        let event = Arc::new(event);
185	        let guard = match self.subscribers.read() {
186	            Ok(g) => g,
187	            Err(poisoned) => poisoned.into_inner(),
188	        };
189	
190	        guard.retain(|subscriber| {
191	            // If the channel is full or disconnected we simply drop the
192	            // subscriber and move on.
193	            subscriber.send(Arc::clone(&event)).is_ok()
194	        });
195	    }
196	
197	    /// Subscribe to the bus returning a dedicated [`Receiver`].
198	    ///
199	    /// The caller **must** keep the receiver alive; once all clones are dropped
200	    /// the subscription automatically ends.
201	    pub fn subscribe(&self) -> Receiver<Arc<DomainEvent>> {
202	        let (tx, rx) = unbounded();
203	
204	        {
205	            let mut guard = self
206	                .subscribers
207	                .write()
208	                .expect("EventBus subscribers lock poisoned");
209	            guard.push(tx);
210	        }
211	
212	        rx
213	    }
214	}
