15	/// Public accessor to the global [`EventBus`].
16	///
17	/// The bus is a lazily-initialized singleton that lives for the entire
18	/// lifetime of the application.  Sub-modules obtain a handle through
19	/// the free [`bus()`] function and then call [`EventBus::dispatch`] or
20	/// [`EventBus::subscribe`] as required.
21	///
22	/// Example
23	/// -------
24	/// ```rust
25	/// use geopalette_pulse_core::services::event_bus::{bus, AppEvent};
26	///
27	/// // PRODUCTION CODE: triggered by a GPS callback.
28	/// bus().dispatch(AppEvent::from(LocationUpdate { /* … */ }));
29	///
30	/// // UNIT TEST: listen for events.
31	/// let mut rx = bus().subscribe();
32	/// let evt = rx.recv().await.unwrap();
33	/// assert!(matches!(*evt, AppEvent::LocationUpdated(_)));
34	/// ```
35	pub fn bus() -> &'static EventBus {
36	    &EVENT_BUS
37	}
38	
39	/// Capacity of the underlying broadcast channel.
40	///
41	/// Chosen empirically—large enough to absorb a short burst of events
42	/// while keeping memory usage bounded.  When the buffer is full, the
43	/// oldest message is discarded for slow receivers.
44	const CHANNEL_CAPACITY: usize = 256;
45	
46	/// Lazily-initialised global bus instance.
47	static EVENT_BUS: Lazy<EventBus> = Lazy::new(|| EventBus::new(CHANNEL_CAPACITY));
48	
49	/// Central event dispatcher based on Tokio’s broadcast channel.
50	///
51	/// The implementation adopts the Observer pattern: multiple independent
52	/// observers may subscribe to the same stream without being aware of
53	/// each other.  Internally a broadcast channel is used so that every
54	/// subscriber sees **all** events in the same order.
55	///
56	/// Cloning `EventBus` is cheap because it only duplicates an [`Arc`]
57	/// pointing to the underlying channel [`Sender`].
58	#[derive(Clone, Debug)]
59	pub struct EventBus {
60	    tx: Sender<Arc<AppEvent>>,
61	}
62	
63	impl EventBus {
64	    /// Creates a new bus instance with the given channel capacity.
65	    fn new(capacity: usize) -> Self {
66	        let (tx, _rx) = broadcast::channel(capacity);
67	        Self { tx }
68	    }
69	
70	    /// Registers a new subscriber and returns a [`Receiver`] to it.
71	    ///
72	    /// Each receiver has its own cursor into the ring-buffer, so slow
73	    /// consumers do **not** block the producer.  If a receiver falls
74	    /// behind it will miss messages; it is the consumer’s responsibility
75	    /// to handle `RecvError::Lagged`.
76	    pub fn subscribe(&self) -> Receiver<Arc<AppEvent>> {
77	        self.tx.subscribe()
78	    }
79	
80	    /// Dispatches an event to all active subscribers.
81	    ///
82	    /// The returned value is the number of receivers that successfully
83	    /// picked up the event.  Failure to deliver is not considered fatal;
84	    /// the most common reason is “no active subscriber”, which is fine
85	    /// for fire-and-forget telemetry such as analytics.
86	    pub fn dispatch<E>(&self, event: E) -> usize
87	    where
88	        E: Into<AppEvent>,
89	    {
90	        let wrapped = Arc::new(event.into());
91	        match self.tx.send(wrapped) {
92	            Ok(cnt) => cnt,
93	            Err(e) => {
94	                log::debug!("event dispatch failed (no subscribers?): {:?}", e.0);
95	                0
96	            }
97	        }
98	    }
99	}
