263	/// Simple blocking API for subscribers that run on non-Tokio threads.
264	///
265	/// The function will block until the next event arrives or the channel
266	/// is closed (which only happens on app shutdown).
267	///
268	/// Example
269	/// -------
270	/// ```no_run
271	/// use std::thread;
272	/// use geopalette_pulse_core::services::event_bus::{bus, AppEvent, next_blocking};
273	///
274	/// thread::spawn(|| {
275	///     loop {
276	///         match next_blocking() {
277	///             Some(AppEvent::CrashDetected(report)) => println!("Crashed: {:?}", report),
278	///             Some(_) => {} // ignore other events
279	///             None => break, // channel closed
280	///         }
281	///     }
282	/// });
283	/// ```
284	pub fn next_blocking() -> Option<Arc<AppEvent>> {
285	    let rx = bus().subscribe();
286	    rx.recv().ok()
287	}
