160	//! Thread-safe, high-performance event bus implementation.
161	//!
162	//! Uses a broadcast channel under the hood, but also stores an internal
163	//! registry so that handlers can be removed at runtime.
164	
165	use crate::{error::GeoCoreError, events::DomainEvent};
166	use crossbeam_channel::{unbounded, Receiver, Sender};
167	use once_cell::sync::Lazy;
168	use parking_lot::RwLock;
169	use std::{
170	    collections::HashMap,
171	    sync::{Arc, Weak},
172	};
173	use uuid::Uuid;
174	
175	/// Opaque identifier for a registered handler.
176	pub type HandlerId = Uuid;
177	
178	/// Function signature of an event handler.
179	type DynHandler = dyn Fn(&DomainEvent) + Send + Sync + 'static;
180	
181	/// EventBus trait.
182	///
183	/// Offers methods to publish and subscribe to domain events.  Implemented by
184	/// [`SimpleBus`], but may be swapped for alternative strategies (e.g.,
185	/// async/actor-based) without changing call-sites.
186	pub trait EventBus: Send + Sync + 'static {
187	    /// Publish an event to all subscribers.
188	    fn post(&self, event: DomainEvent);
189	
190	    /// Register a handler. Returns the assigned [`HandlerId`].
191	    fn subscribe<F>(&self, handler: F) -> Result<HandlerId, GeoCoreError>
192	    where
193	        F: Fn(&DomainEvent) + Send + Sync + 'static;
194	
195	    /// Remove a handler if present.
196	    fn unsubscribe(&self, id: HandlerId);
197	}
198	
199	/// Blanket extension trait for syntactic sugar.
200	pub trait EventBusExt {
201	    /// Convenience method to post through the global bus.
202	    fn post(event: DomainEvent) {
203	        crate::bus::global_bus().post(event);
204	    }
205	}
206	impl<T: EventBus> EventBusExt for T {}
207	
208	/// A minimalistic, lock-free publish/subscribe implementation.
209	#[derive(Debug)]
210	pub struct SimpleBus {
211	    tx: Sender<DomainEvent>,
212	    /// Receivers are weak-referenced to accommodate dynamic un/sub.
213	    receivers: RwLock<HashMap<HandlerId, Weak<Receiver<DomainEvent>>>>,
214	}
215	
216	impl Default for SimpleBus {
217	    fn default() -> Self {
218	        let (tx, _rx) = unbounded::<DomainEvent>();
219	        Self {
220	            tx,
221	            receivers: RwLock::new(HashMap::new()),
222	        }
223	    }
224	}
225	
226	impl SimpleBus {
227	    /// Spawn an internal worker that will forward events to handlers.
228	    fn spawn_dispatch_loop(self: &Arc<Self>) {
229	        let rx = self.tx.subscribe();
230	        let bus = Arc::clone(self);
231	        std::thread::Builder::new()
232	            .name("gp_core_dispatch".into())
233	            .spawn(move || {
234	                for event in rx.iter() {
235	                    // Snapshot current handlers.
236	                    let handlers: Vec<Arc<DynHandler>> = {
237	                        let map = bus.receivers.read();
238	                        map.values()
239	                            .filter_map(Weak::upgrade)
240	                            .map(|chan| {
241	                                // Each handler owns a rx, we pull and invoke.
242	                                chan
243	                            })
244	                            .collect()
245	                    };
246	                    for handler_rx in handlers {
247	                        // Each handler channel contains a single pointer to the closure.
248	                        if let Ok(handler_ptr) = handler_rx.try_recv() {
249	                            handler_ptr(event.clone());
250	                            // push back pointer for next use
251	                            let _ = handler_rx.send(handler_ptr);
252	                        }
253	                    }
254	                }
255	            })
256	            .expect("failed to spawn dispatch loop");
257	    }
258	}
259	
260	impl EventBus for SimpleBus {
261	    fn post(&self, event: DomainEvent) {
262	        let _ = self.tx.send(event);
263	    }
264	
265	    fn subscribe<F>(&self, handler: F) -> Result<HandlerId, GeoCoreError>
266	    where
267	        F: Fn(&DomainEvent) + Send + Sync + 'static,
268	    {
269	        let id = HandlerId::new_v4();
270	        if self.receivers.read().contains_key(&id) {
271	            return Err(GeoCoreError::DuplicateHandler);
272	        }
273	
274	        let arc_handler: Arc<DynHandler> = Arc::new(handler);
275	        let (chan_tx, chan_rx) = unbounded::<Arc<DynHandler>>();
276	        // Seed with the handler itself for the first dispatch.
277	        chan_tx.send(arc_handler).ok();
278	
279	        self.receivers
280	            .write()
281	            .insert(id, Arc::downgrade(&Arc::new(chan_rx)));
282	
283	        Ok(id)
284	    }
285	
286	    fn unsubscribe(&self, id: HandlerId) {
287	        self.receivers.write().remove(&id);
288	    }
289	}
290	
291	/// Global singleton bus.
292	static GLOBAL_BUS: Lazy<Arc<SimpleBus>> = Lazy::new(|| {
293	    let bus = Arc::new(SimpleBus::default());
294	    bus.spawn_dispatch_loop();
295	    bus
296	});
297	
298	/// Obtain a shared reference to the global event bus.
299	pub fn global_bus() -> Arc<dyn EventBus> {
300	    Arc::clone(&*GLOBAL_BUS) as Arc<dyn EventBus>
301	}
