2	//! geo_palette_pulse_core::config
3	//! ---------------------------------------------------------------
4	//! Centralised runtime/compile-time configuration for
5	//!     GeoPalette Pulse – Creative Mobile Utility
6	//!
7	//! Responsibilities
8	//! ----------------
9	//! • Expose a strongly-typed, thread-safe global `Config` singleton  
10	//! • Load/merge configuration from (in-order of precedence):
11	//!      1. Explicit path provided by caller
12	//!      2. `$GPP_CONFIG` environment variable (absolute or relative)
13	//!      3. Built-in defaults (compile-time constants)
14	//! • Allow hot-reloading while notifying interested parties (Observer)
15	//! • Keep compile-time feature gates in sync with runtime flags
16	//! ---------------------------------------------------------------
17	
18	use once_cell::sync::Lazy;
19	use serde::Deserialize;
20	use std::{
21	    env,
22	    fs,
23	    path::{Path, PathBuf},
24	    sync::{mpsc, Arc, RwLock, RwLockReadGuard},
25	};
26	
27	/// Channel buffer size for configuration update broadcasts.
28	const BROADCAST_CAPACITY: usize = 8;
29	
30	/// Convenient alias for the broadcast sender used by the config bus.
31	type ConfigSender = mpsc::Sender<Arc<Config>>;
32	/// Convenient alias for the broadcast receiver used by observers.
33	pub type ConfigReceiver = mpsc::Receiver<Arc<Config>>;
34	
35	/// Applications modules listen for `Config` changes through this function.
36	///
37	/// Any value received on the returned `ConfigReceiver` is _guaranteed_ to be a
38	/// clone of the **entire** `Config` state at the time of the update.
39	pub fn subscribe() -> ConfigReceiver {
40	    CONFIG_BUS
41	        .read()
42	        .expect("poisoned CONFIG_BUS")
43	        .0
44	        .subscribe()
45	}
46	
47	/// Public accessor for read-only usage of the current `Config`.
48	///
49	/// Internally we guard the global state by an `RwLock`; external callers never
50	/// obtain mutable access but can still read safely and cheaply.
51	pub fn current() -> RwLockReadGuard<'static, Config> {
52	    CONFIG.read().expect("poisoned CONFIG lock")
53	}
54	
55	/// Attempts to hot-reload the configuration from the provided path.
56	///
57	/// Upon successful load:
58	/// * The global singleton is atomically swapped using write-locks
59	/// * All observers receive the updated, _arc-wrapped_ instance
60	///
61	/// It is intentionally **synchronous**; the caller decides whether to off-load
62	/// the file-IO portion to a background thread or async runtime.
63	pub fn reload_from<P: AsRef<Path>>(path: P) -> Result<(), ConfigError> {
64	    let cfg = Config::from_file(path)?;
65	    dispatch_update(cfg);
66	    Ok(())
67	}
68	
69	/// Loads configuration solely from process environment variables.
70	/// Mostly useful for unit tests and container-based deployments.
71	pub fn reload_from_env() -> Result<(), ConfigError> {
72	    let cfg = Config::from_env()?;
73	    dispatch_update(cfg);
74	    Ok(())
75	}
76	
77	/// Internal helper that replaces the global singleton and broadcasts events.
78	fn dispatch_update(new_cfg: Config) {
79	    let mut write = CONFIG.write().expect("poisoned CONFIG lock");
80	    *write = new_cfg.clone(); // keep local copy
81	    let arc_cfg = Arc::new(new_cfg);
82	
83	    // Broadcast — ignore send-errors caused by disconnected receivers.
84	    let _ = CONFIG_BUS
85	        .read()
86	        .expect("poisoned CONFIG_BUS")
87	        .0
88	        .send(Arc::clone(&arc_cfg));
89	}
90	
91	/// `ConfigBus` is a simple wrapper providing `subscribe` semantics on top of a
92	/// multi-producer, multi-consumer channel.  Multiple threads may subscribe;
93	/// every update is sent to _all_ cloned receivers.
94	#[derive(Debug)]
95	struct ConfigBus(ConfigSender);
96	
97	impl ConfigBus {
98	    fn new() -> Self {
99	        let (tx, _rx) = mpsc::sync_channel::<Arc<Config>>(BROADCAST_CAPACITY);
100	        Self(tx)
101	    }
102	
103	    fn subscribe(&self) -> ConfigReceiver {
104	        let (_, rx) = mpsc::sync_channel::<Arc<Config>>(BROADCAST_CAPACITY);
105	        // Create a new channel pair, clone the sender and hook into our bus.
106	        let cloned_sender = self.0.clone();
107	        let (local_tx, local_rx) = mpsc::sync_channel(BROADCAST_CAPACITY);
108	        std::thread::spawn(move || {
109	            while let Ok(cfg) = cloned_sender.recv() {
110	                // Ignore send-errors => receiving side closed.
111	                let _ = local_tx.send(cfg.clone());
112	            }
113	        });
114	        local_rx
115	    }
116	}
117	
118	// ---------- Global Singletons ------------------------------------------------
119	static CONFIG: Lazy<RwLock<Config>> = Lazy::new(|| {
120	    let cfg = Config::bootstrap().unwrap_or_default();
121	    RwLock::new(cfg)
122	});
123	
124	static CONFIG_BUS: Lazy<RwLock<ConfigBus>> = Lazy::new(|| RwLock::new(ConfigBus::new()));
125	
126	// ---------- Config Domain Model ---------------------------------------------
127	#[derive(Debug, Clone, Deserialize)]
128	pub struct Config {
129	    pub app: AppConfig,
130	    pub features: FeatureFlags,
131	    pub endpoints: ServiceEndpoints,
132	    pub security: SecurityConfig,
133	}
134	
135	impl Config {
136	    /// Merge strategy: call-site chooses precedence by providing sources first.
137	    fn merge_hierarchy(primary: Option<Self>, fallback: Self) -> Self {
138	        if let Some(primary) = primary {
139	            Self {
140	                app: primary.app.or(fallback.app),
141	                features: primary.features.or(fallback.features),
142	                endpoints: primary.endpoints.or(fallback.endpoints),
143	                security: primary.security.or(fallback.security),
144	            }
145	        } else {
146	            fallback
147	        }
148	    }
149	
150	    /// Bootstrap sequence used by global static initialiser.
151	    fn bootstrap() -> Result<Self, ConfigError> {
152	        // Precedence:
153	        // ──1── explicit path via env var
154	        // ──2── process environment variables
155	        // ──3── hard-coded defaults
156	        let env_path = env::var("GPP_CONFIG").ok().map(PathBuf::from);
157	        let mut cfg = Self::default();
158	
159	        if let Some(path) = env_path {
160	            cfg = Self::merge_hierarchy(Some(Self::from_file(&path)?), cfg);
161	        }
162	        cfg = Self::merge_hierarchy(Some(Self::from_env()?), cfg);
163	
164	        Ok(cfg)
165	    }
166	
167	    /// Loads configuration from an on-disk TOML or JSON file.
168	    pub fn from_file<P: AsRef<Path>>(path: P) -> Result<Self, ConfigError> {
169	        if !path.as_ref().exists() {
170	            return Err(ConfigError::FileNotFound(path.as_ref().to_owned()));
171	        }
172	
173	        let data = fs::read_to_string(&path)?;
174	        let cfg = if path
175	            .as_ref()
176	            .extension()
177	            .map(|ext| ext == "json")
178	            .unwrap_or(false)
179	        {
180	            serde_json::from_str(&data)?
181	        } else {
182	            toml::from_str(&data)?
183	        };
184	
185	        Ok(cfg)
186	    }
187	
188	    /// Loads configuration solely from env vars (prefixed with `GPP_`).
189	    pub fn from_env() -> Result<Self, ConfigError> {
190	        let mut cfg = Self::default();
191	
192	        if let Ok(var) = env::var("GPP_ENV") {
193	            cfg.app.environment = var;
194	        }
195	
196	        // Boolean feature flags
197	        cfg.features.location_services = env_flag("GPP_FEATURE_LOCATION", cfg.features.location_services);
198	        cfg.features.in_app_purchases = env_flag("GPP_FEATURE_IAP", cfg.features.in_app_purchases);
199	        cfg.features.biometric_auth = env_flag("GPP_FEATURE_BIO", cfg.features.biometric_auth);
200	        cfg.features.crash_reporting = env_flag("GPP_FEATURE_CRASH", cfg.features.crash_reporting);
201	        cfg.features.social_sharing = env_flag("GPP_FEATURE_SHARE", cfg.features.social_sharing);
202	
203	        // Endpoints overrides
204	        if let Ok(uri) = env::var("GPP_ENDPOINT_WEATHER") {
205	            cfg.endpoints.weather_api = uri;
206	        }
207	        if let Ok(uri) = env::var("GPP_ENDPOINT_ANALYTICS") {
208	            cfg.endpoints.analytics_api = uri;
209	        }
210	
211	        Ok(cfg)
212	    }
213	}
