34	/// Global, lazily-initialised collector used by the tests to tap into the
35	/// Observer bus and keep a record of every event that flows through.
36	///
37	/// NOTE: This *only* exists in the test binary; nothing is wired into the
38	///       production app.
39	static CAPTURED_EVENTS: Lazy<Arc<Mutex<Vec<DomainEvent>>>> =
40	    Lazy::new(|| Arc::new(Mutex::new(Vec::new())));
41	
42	/// Registers an event listener that pushes every incoming event into
43	/// `CAPTURED_EVENTS`. It is idempotent, so calling it multiple times is cheap.
44	///
45	/// The listener is attached once per **test process**, *not* once per test
46	/// function. This saves allocations and keeps the global state predictable.
47	fn init_event_capture() {
48	    static REGISTER: Lazy<()> = Lazy::new(|| {
49	        let bus = EventBus::global();
50	        let sink = CAPTURED_EVENTS.clone();
51	        bus.subscribe(move |evt| {
52	            sink.lock().expect("poisoned").push(evt.clone());
53	        });
54	    });
55	
56	    // Force initialisation
57	    Lazy::force(&REGISTER);
58	}
59	
60	/// Utility that drains—and returns—the captured event buffer.
61	fn take_captured_events() -> Vec<DomainEvent> {
62	    let mut guard = CAPTURED_EVENTS.lock().expect("poisoned");
63	    guard.drain(..).collect()
64	}
