147	/// Verifies that the Observer bus can keep up with *N* rapid-fire palette
148	/// generations happening in parallel.
149	///
150	/// The test uses Tokio’s multi-threaded runtime because that is what the real
151	/// app runs on.
152	#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
153	async fn concurrent_palette_generation() {
154	    init_event_capture();
155	
156	    const TASKS: usize = 64;
157	    let generator = Arc::new(PaletteGenerator::new(fixture_generator_config()));
158	
159	    let mut handles = Vec::with_capacity(TASKS);
160	    for _ in 0..TASKS {
161	        let gen_clone = generator.clone();
162	        handles.push(task::spawn(async move {
163	            gen_clone
164	                .generate(&fixture_location(), &fixture_environment())
165	                .expect("palette generation should succeed")
166	        }));
167	    }
168	
169	    // Await all tasks, fail fast if any returned an error
170	    let palettes: Vec<Palette> = futures::future::try_join_all(handles)
171	        .await
172	        .expect("tasks failed");
173	
174	    // Invariants -------------------------------------------------------------
175	    assert_eq!(palettes.len(), TASKS, "one palette per task");
176	    // Every palette ID must be unique
177	    let ids: HashSet<_> = palettes.iter().map(|p| p.id()).collect();
178	    assert_eq!(ids.len(), TASKS, "palette IDs collide under concurrency");
179	
180	    // The Observer bus should have dispatched a matching number of events
181	    let events = take_captured_events();
182	    let generated_evt_count = events
183	        .iter()
184	        .filter(|e| matches!(e, DomainEvent::PaletteGenerated(_)))
185	        .count();
186	    assert_eq!(
187	        generated_evt_count, TASKS,
188	        "Observer bus dropped events under load"
189	    );
