2	//! GeoPalette Pulse – Core Service Layer
3	//!
4	//! This module collects public‐facing service traits and exposes a simple, yet
5	//! powerful *Service Locator* (a Singleton with factory capabilities) used by
6	//! the rest of the application.  
7	//!
8	//! The goal is to keep concrete service implementations out of dependant
9	//! modules so that they can be replaced (e.g. mocked) effortlessly during unit
10	//! testing or platform–specific compilation.  
11	//!
12	//! Architecturally this module sits underneath the higher‐level MVVM layer and
13	//! just above low-level adapters (location SDK, payment SDK, etc.).  
14	//!
15	//! Enabled compile-time features control which concrete implementation is wired
16	//! up by default. Unsupported platforms/features automatically fall back to a
17	//! `Noop*` implementation that fulfils the interface without doing anything,
18	//! making it safe for unit tests and desktop targets.
19	//!
20	//! # Features
21	//! * `location_services`
22	//! * `in_app_purchases`
23	//! * `biometric_auth`
24	//! * `crash_reporting`
25	//! * `social_sharing`
26	
27	// External Dependencies -----------------------------------------------------
28	use futures_core::Stream;
29	use once_cell::sync::Lazy;
30	use std::{
31	    collections::HashMap,
32	    fmt::Debug,
33	    sync::{Arc, RwLock},
34	};
35	use thiserror::Error;
36	use uuid::Uuid;
37	
38	// Re-export commonly used types so callers can `use crate::services::*;`
39	pub use auth::BiometricAuthService;
40	pub use bus::{DomainEventBus, Event, EventBus};
41	pub use crash::CrashReporterService;
42	pub use location::LocationService;
43	pub use palette::PaletteService;
44	pub use purchase::InAppPurchaseService;
45	pub use sharing::SocialSharingService;
46	
47	// ---------------------------------------------------------------------------
48	//  Public Error Type
49	// ---------------------------------------------------------------------------
50	
51	/// Umbrella error description for the service layer.
52	#[derive(Debug, Error)]
53	pub enum ServiceError {
54	    #[error("the requested service is not registered")]
55	    NotRegistered,
56	    #[error("an underlying service failed: {0}")]
57	    Inner(#[from] anyhow::Error),
58	}
59	
60	// ---------------------------------------------------------------------------
61	//  Service Locator
62	// ---------------------------------------------------------------------------
63	
64	/// Marker trait for all services handled by the [`ServiceLocator`].
65	pub trait Service: Send + Sync + 'static {}
66	
67	impl<T: Send + Sync + 'static> Service for T {}
68	
69	type DynService = Arc<dyn Service>;
70	
71	/// Thread-safe global service registry.
72	///
73	/// The struct is intentionally kept private—access happens via
74	/// `ServiceLocator::get()` and `ServiceLocator::register()`.
75	struct Registry {
76	    services: RwLock<HashMap<&'static str, DynService>>,
77	}
78	
79	impl Registry {
80	    fn new() -> Self {
81	        Self {
82	            services: RwLock::new(HashMap::new()),
83	        }
84	    }
85	
86	    fn get<S: ?Sized + Service>(&self, key: &'static str) -> Result<Arc<S>, ServiceError> {
87	        self.services
88	            .read()
89	            .expect("poisoned lock")
90	            .get(key)
91	            .cloned()
92	            .ok_or(ServiceError::NotRegistered)
93	            .and_then(|svc| {
94	                svc.downcast_arc::<S>()
95	                    .map_err(|_| ServiceError::NotRegistered)
96	            })
97	    }
98	
99	    fn register<S: Service>(&self, key: &'static str, service: S) {
100	        let mut map = self.services.write().expect("poisoned lock");
101	        map.insert(key, Arc::new(service));
102	    }
103	}
104	
105	/// Global registry instance (Singleton).
106	static REGISTRY: Lazy<Registry> = Lazy::new(Registry::new);
107	
108	/// User-facing façade for the global service registry.
109	///
110	/// Example
111	/// -------
112	/// ```ignore
113	/// let location = ServiceLocator::get::<dyn LocationService>()?;
114	/// location.start();
115	/// ```
116	pub struct ServiceLocator;
117	
118	impl ServiceLocator {
119	    /// Obtain a concrete service by trait object type.
120	    pub fn get<S: ?Sized + Service>(key: &'static str) -> Result<Arc<S>, ServiceError> {
121	        REGISTRY.get::<S>(key)
122	    }
123	
124	    /// Register a concrete service.
125	    pub fn register<S: Service>(key: &'static str, service: S) {
126	        REGISTRY.register(key, service)
127	    }
128	}
