130	// ---------------------------------------------------------------------------
131	//  Domain Event Bus (Observer Pattern)
132	// ---------------------------------------------------------------------------
133	mod bus {
134	    use super::*;
135	    use dashmap::DashMap;
136	    use futures_channel::mpsc::{unbounded, UnboundedReceiver, UnboundedSender};
137	
138	    /// Base trait for all events flowing through the domain bus.
139	    pub trait Event: Send + Sync + Debug {
140	        /// Each event receives a UUID so listeners can correlate them.
141	        fn id(&self) -> Uuid;
142	    }
143	
144	    /// Strongly typed Observer bus used by the entire application.
145	    pub trait EventBus: Service {
146	        /// Publish an event to all subscribers.
147	        fn publish<E: Event + 'static>(&self, event: E);
148	
149	        /// Subscribe to a specific event type.  
150	        /// Returns an `UnboundedReceiver<E>` that yields all incoming events of
151	        /// that type.
152	        fn subscribe<E: Event + 'static>(&self) -> UnboundedReceiver<E>;
153	    }
154	
155	    /// Multi-producer, multi-consumer event bus implementation.
156	    #[derive(Default)]
157	    pub struct DomainEventBus {
158	        // Map: TypeId → Vec<UnboundedSender<Box<dyn Any + Send + Sync>>>
159	        channels: DashMap<std::any::TypeId, Vec<UnboundedSender<Box<dyn std::any::Any + Send>>>>,
160	    }
161	
162	    impl Service for DomainEventBus {}
163	
164	    impl DomainEventBus {
165	        pub fn new() -> Self {
166	            Self::default()
167	        }
168	    }
169	
170	    impl EventBus for DomainEventBus {
171	        fn publish<E: Event + 'static>(&self, event: E) {
172	            let type_id = std::any::TypeId::of::<E>();
173	            if let Some(senders) = self.channels.get(&type_id) {
174	                for tx in senders.iter() {
175	                    // Ignore send errors (receiver might be dropped)
176	                    let _ = tx.unbounded_send(Box::new(event.clone()));
177	                }
178	            }
179	        }
180	
181	        fn subscribe<E: Event + 'static>(&self) -> UnboundedReceiver<E> {
182	            let type_id = std::any::TypeId::of::<E>();
183	            let (tx, rx) = unbounded::<Box<dyn std::any::Any + Send>>();
184	
185	            self.channels
186	                .entry(type_id)
187	                .or_default()
188	                .push(tx);
189	
190	            // Map Any → concrete event type
191	            let (mapped_tx, mapped_rx) = unbounded::<E>();
192	            tokio::spawn(async move {
193	                use futures_util::StreamExt;
194	                let mut rx = rx;
195	                while let Some(raw) = rx.next().await {
196	                    if let Ok(evt) = raw.downcast::<E>() {
197	                        // ignore failures
198	                        let _ = mapped_tx.unbounded_send(*evt);
199	                    }
200	                }
201	            });
202	
203	            mapped_rx
204	        }
205	    }
206	}
