662	trait ArcAnyDowncastExt {
663	    fn downcast_arc<T: ?Sized + 'static>(self: Arc<Self>) -> Result<Arc<T>, Arc<Self>>
664	    where
665	        Self: std::any::Any + Sized;
666	}
667	
668	impl ArcAnyDowncastExt for dyn Service {
669	    fn downcast_arc<T: ?Sized + 'static>(self: Arc<Self>) -> Result<Arc<T>, Arc<Self>>
670	    where
671	        Self: std::any::Any + Sized,
672	    {
673	        if (*self).type_id() == std::any::TypeId::of::<T>() {
674	            let ptr = Arc::into_raw(self) as *const T;
675	            Ok(unsafe { Arc::from_raw(ptr) })
676	        } else {
677	            Err(self)
678	        }
679	    }
680	}
