2	//! geo_palette_pulse_core::view_models
3	//! -----------------------------------
4	//! View-models live in this module.  Every view-model is an observer that
5	//! listens to `DomainEvent`s published on the global [`EventBus`] and
6	//! translates them into UI-ready, queryable state.  
7	//!
8	//! The code follows the MVVM pattern, shielding the application’s UI layer from
9	//! the noisy details of the domain layer while keeping everything fully
10	//! reactive and test-friendly.
11	
12	#![allow(dead_code)]
13	
14	use std::{collections::HashMap, sync::Arc};
15	
16	use async_trait::async_trait;
17	use parking_lot::RwLock;
18	use uuid::Uuid;
19	
20	use crate::{
21	    error::AppError,
22	    events::{DomainEvent, EventBus, ObserverId},
23	};
24	
25	/// Convenient alias used throughout the VM layer.
26	type VmResult<T> = Result<T, AppError>;
27	
28	/// =============================================================================================
29	/// Shared traits / infrastructure
30	/// =============================================================================================
31	
32	/// A `ViewModel` observes the [`EventBus`] and keeps an internal, queryable
33	/// state that the UI can bind to.
34	#[async_trait]
35	pub trait ViewModel: Send + Sync + 'static {
36	    /// Unique, stable identifier for diagnostic & registry purposes.
37	    ///
38	    /// A default implementation using [`Uuid`] is provided but individual VMs
39	    /// are free to override this if they have a more convenient primary key.
40	    fn id(&self) -> Uuid {
41	        Uuid::new_v4()
42	    }
43	
44	    /// Called by the [`ViewModelRegistry`] whenever a new [`DomainEvent`]
45	    /// comes in.  
46	    ///
47	    /// Returning an `Err` will never bring down the app—errors are reported to
48	    /// the global error handler and the VM stays subscribed unless it decides
49	    /// to panic.
50	    async fn on_event(&self, event: &DomainEvent) -> VmResult<()>;
51	}
52	
53	/// A thin façade in front of the global [`EventBus`].  Keeps a map of all the
54	/// active view-models and forwards events to them.
55	///
56	/// The registry owns no view-model data. Instead it stores reference-counted
57	/// `Arc`s so that UI widgets, tests, and diagnostics can hold their own
58	/// pointers without worrying about lifetimes.
59	pub struct ViewModelRegistry {
60	    /// The singleton `EventBus` through which domain events flow.
61	    bus: Arc<EventBus>,
62	    /// Map of observer id ➜ view-model instance.
63	    view_models: RwLock<HashMap<ObserverId, Arc<dyn ViewModel>>>,
64	}
65	
66	impl ViewModelRegistry {
67	    /// Creates a new, *empty* registry.
68	    pub fn new(bus: Arc<EventBus>) -> Self {
69	        Self {
70	            bus,
71	            view_models: RwLock::new(HashMap::new()),
72	        }
73	    }
74	
75	    /// Registers a view-model with the registry *and* subscribes it to the
76	    /// event bus in one shot.  Returns the auto-generated [`ObserverId`].
77	    pub fn register<V>(&self, vm: V) -> ObserverId
78	    where
79	        V: ViewModel,
80	    {
81	        let vm = Arc::new(vm);
82	        let id = self
83	            .bus
84	            .subscribe({
85	                // We clone the Arc so the closure has its own handle.
86	                let vm_clone = Arc::clone(&vm);
87	                move |evt: &DomainEvent| {
88	                    // We cannot `.await` inside the subscribe callback, so we
89	                    // off-load to the async runtime.  If the runtime is not
90	                    // Tokio this compiles under `async-compat`.
91	                    let cloned_evt = evt.clone();
92	                    let vm_for_task = Arc::clone(&vm_clone);
93	                    tokio::spawn(async move {
94	                        if let Err(err) = vm_for_task.on_event(&cloned_evt).await {
95	                            tracing::error!(
96	                                vm = %vm_for_task.id(),
97	                                error = ?err,
98	                                "view-model failed to process event",
99	                            );
100	                        }
101	                    });
102	                }
103	            })
104	            .expect("Failed to subscribe ViewModel to EventBus");
105	
106	        self.view_models.write().insert(id, vm);
107	        id
108	    }
109	
110	    /// Unregisters the given view-model, detaching it from the event bus.
111	    pub fn unregister(&self, id: ObserverId) {
112	        self.view_models.write().remove(&id);
113	        if let Err(e) = self.bus.unsubscribe(id) {
114	            tracing::warn!(observer = %id, error = ?e, "Failed to unsubscribe observer");
115	        }
116	    }
117	
118	    /// Fetches a view-model by its [`ObserverId`].
119	    pub fn get(&self, id: ObserverId) -> Option<Arc<dyn ViewModel>> {
120	        self.view_models.read().get(&id).cloned()
121	    }
122	
123	    /// Returns *all* registered view-models (snapshot).
124	    pub fn all(&self) -> Vec<Arc<dyn ViewModel>> {
125	        self.view_models.read().values().cloned().collect()
126	    }
127	}
