2	//! GeoPalette Pulse — Domain Layer
3	//! =================================
4	//! This module represents the *domain* (a.k.a. business-logic) layer of the
5	//! GeoPalette Pulse core.  It is deliberately isolated from UI, storage,
6	//! network or any other infrastructure code.  The only outward-facing surface
7	//! is a thread-safe, runtime‐configurable *event bus* that applies the classic
8	//! Observer pattern so that the rest of the application can *react* to changes
9	//! in user context without tight coupling.
10	//
11	//! Guidelines & Guarantees
12	//! -----------------------
13	//! 1. All messages flowing through the bus are represented by `DomainEvent`.
14	//! 2. The bus is *broadcast-only* — events can be observed but never mutated.
15	//! 3. Registration / de-registration is O(1) and *lock-free* for reads.
16	//! 4. The module is `no_std`-ready except for the optional, feature-gated
17	//!    sub-modules that rely on OS or network facilities.
18	//!
19	//! The implementation favours *pragmatic* ergonomics over absolute generic
20	//! purity.  In other words: it should be pleasant to use in day-to-day
21	//! application code, while still remaining fully testable and deterministic.
22	
23	#![allow(clippy::module_inception)]
24	
25	use std::collections::HashMap;
26	use std::sync::Arc;
27	
28	use once_cell::sync::Lazy;
29	use parking_lot::RwLock;
30	use serde::{Deserialize, Serialize};
31	use thiserror::Error;
32	use uuid::Uuid;
33	
34	// -----------------------------------------------------------------------------
35	//  Public Re-exports
36	// -----------------------------------------------------------------------------
37	pub use bus::{EventBus, GLOBAL_BUS};
38	pub use errors::{DomainError, EventBusError, EventHandlerError, Result};
39	pub use events::{
40	    BiometricEvent, BrushPurchase, DomainEvent, LocationUpdate, Palette, PaletteEvent,
41	    PaletteGenerated, ShareOutcome,
42	};
43	pub use value_objects::{BrushId, PaletteId, UserId};
44	
45	// -----------------------------------------------------------------------------
46	//  Sub-modules (kept private except for explicit `pub use` above)
47	// -----------------------------------------------------------------------------
48	mod value_objects {
49	    //! *Value Objects* — small, self-contained data-types that exist by virtue
50	    //! of their **value** rather than their identity.
51	
52	    use serde::{Deserialize, Serialize};
53	    use std::fmt;
54	    use uuid::Uuid;
55	
56	    macro_rules! new_uuid_type {
57	        ($name:ident) => {
58	            #[derive(Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
59	            pub struct $name(Uuid);
60	
61	            impl $name {
62	                pub fn new() -> Self {
